input.command:
cd /workspace/dataset && rep() { local n=$1 c=$2 s=""; for ((i=0;i<n;i++)); do s+="$c"; done; printf '%s' "$s"; }
for n in 0 1 62 63 64 126 127 128 252 253 254 255 256 257 511 512 1023 1024 2000; do
  s="$(rep $n a)"$'\xff'; printf 'a*%-5s+FF => ' "$n"; ./test4_executable "$s" | tr '\n' ' ';
  s2=$'\xff'"$(rep $n a)"; printf '   | FF+a*%-5s => ' "$n"; ./test4_executable "$s2" | tr '\n' ' '; echo; done
